def is_cube(n):
    if n == 0: return True
    r = round(abs(n)**(1/3))
    if r**3 == abs(n):
        return r if n > 0 else -r
    return None

def solve():
    solutions = [-3] # x = -3 is a solution
    for g in [1, 5, 13, 65]:
        C = 65 // g
        divs = []
        for i in range(1, int(C**0.5) + 1):
            if C % i == 0:
                divs.append(i)
                if i*i != C:
                    divs.append(C // i)

        for d in divs:
            quad_delta = 12 * C / d - 3 * d**2
            if quad_delta >= 0:
                delta_sqrt = int(quad_delta**0.5)
                if delta_sqrt**2 == quad_delta:
                    for sign in [1, -1]:
                        num = 3 * d + sign * delta_sqrt
                        if num % 6 == 0:
                            A = num // 6
                            B = A - d
                            if A % 2 == 0:
                                k = A // 2
                                u = g * (k**3)
                                x = u - 3
                                val = (8*x - 41) * (x+3)**2
                                if is_cube(val) is not None:
                                    solutions.append(x)
    return sorted(list(set(solutions)))

