        abs_C = abs(C)
        for i in range(1, int(abs_C**0.5) + 1):
            if abs_C % i == 0:
                divisors.append(i)
                divisors.append(-i)
                if i*i != abs_C:
                    divisors.append(abs_C // i)
                    divisors.append(-(abs_C // i))
        for d in divisors:
            if d == 0: continue
            D = 12 * C / d - 3 * d**2
            if D >= 0:
                sqrt_D = int(D**0.5)
                if sqrt_D * sqrt_D == D:
                    for s in [-1, 1]:
                        num = 3 * d + s * sqrt_D
                        if num % 6 == 0:
                            X = num // 6
                            Y = X - d
